// Open-Meteo responde con listas: la posición 0 de cada lista es hoy.
const config = $('Dónde y cuándo avisar').first().json;
const respuesta = $input.first().json;
const d = respuesta.daily ?? {};
const hoy = (lista) => (Array.isArray(lista) ? lista[0] : null);

// Códigos del tiempo de la Organización Meteorológica Mundial (WMO), los que usa Open-Meteo.
const CIELO = {
  0: 'despejado', 1: 'casi despejado', 2: 'parcialmente nublado', 3: 'nublado',
  45: 'niebla', 48: 'niebla con escarcha',
  51: 'llovizna débil', 53: 'llovizna', 55: 'llovizna intensa', 56: 'llovizna helada', 57: 'llovizna helada intensa',
  61: 'lluvia débil', 63: 'lluvia', 65: 'lluvia fuerte', 66: 'lluvia helada', 67: 'lluvia helada fuerte',
  71: 'nevada débil', 73: 'nevada', 75: 'nevada fuerte', 77: 'granizo fino',
  80: 'chaparrones débiles', 81: 'chaparrones', 82: 'chaparrones violentos', 85: 'chaparrones de nieve', 86: 'chaparrones de nieve fuertes',
  95: 'tormenta eléctrica', 96: 'tormenta con granizo', 99: 'tormenta fuerte con granizo',
};

const p = {
  fecha: hoy(d.time),
  codigo: hoy(d.weather_code),
  maxima: hoy(d.temperature_2m_max),
  minima: hoy(d.temperature_2m_min),
  sensacion: hoy(d.apparent_temperature_max),
  lluvia: hoy(d.precipitation_sum),
  probabilidad: hoy(d.precipitation_probability_max),
  uv: hoy(d.uv_index_max),
};

// Para probar las alertas un día lindo: «simular» en el nodo de configuración.
const simular = String(config.simular ?? 'no').toLowerCase().trim();
if (simular === 'calor') Object.assign(p, { maxima: 39, sensacion: 42, codigo: 1, uv: 12, lluvia: 0, probabilidad: 5 });
if (simular === 'lluvia') Object.assign(p, { lluvia: 28, probabilidad: 95, codigo: 95 });

const alertas = [];
if (p.maxima >= config.calor_maximo_c || p.sensacion >= config.calor_maximo_c) {
  alertas.push(`Calor extremo: máxima de ${p.maxima} °C, con sensación de ${p.sensacion} °C. Tomá agua, buscá sombra y evitá el sol del mediodía.`);
}
if (p.lluvia >= config.lluvia_mm || p.probabilidad >= config.probabilidad_lluvia) {
  alertas.push(`Lluvia: ${p.lluvia} mm y ${p.probabilidad} % de probabilidad. Llevá paraguas y cuidado con las calles que se inundan.`);
}
if ([95, 96, 99].includes(p.codigo)) {
  alertas.push('Tormenta eléctrica: si podés, quedate bajo techo y lejos de árboles aislados.');
}
if (p.uv >= 11) {
  alertas.push(`Rayos UV extremos (índice ${p.uv}): protector solar, gorra y sombra entre las 10 y las 16.`);
}

// La fecha en palabras, con Luxon (DateTime viene incluido en n8n).
const fecha = p.fecha ? DateTime.fromISO(p.fecha).setLocale('es').toFormat("cccc d 'de' LLLL") : 'hoy';

return [{
  json: {
    ciudad: config.ciudad,
    fecha,
    cielo: CIELO[p.codigo] ?? `código del tiempo ${p.codigo}`,
    maxima_c: p.maxima,
    minima_c: p.minima,
    sensacion_maxima_c: p.sensacion,
    lluvia_mm: p.lluvia,
    probabilidad_lluvia: p.probabilidad,
    uv_maximo: p.uv,
    hay_alerta: alertas.length > 0,
    alertas,
    simulado: simular === 'calor' || simular === 'lluvia',
    fuente: 'Datos del tiempo: Open-Meteo.com (CC BY 4.0)',
  },
}];

